essure(myBarometer.bmp085ReadUP());//Get the temperature\n   altitude = myBarometer.calcAltitude(pressure); //Uncompensated calculation - in Meters\n   atm = pressure / 101325;\n\n  Serial.print("Temperature: ");\n  Serial.print(temperature, 2); //display 2 decimal places\n  Serial.println("deg C");\n\n  Serial.print("Pressure: ");\n  Serial.print(pressure, 0); // whole numbers only.\n  Serial.println(" Pa");\n\n  Serial.print("Ralated Atmosphere: ");\n  Serial.println(atm, 4); //display 4 decimal places\n\n  Serial.print("Altitude: ");\n  Serial.print(altitude, 2); //display 2 decimal places\n  Serial.println(" m");\n\n  Serial.println();\n\n  delay(1000); //wait a second and get values again.\n}\n'})}),"\n",(0,t.jsxs)(r.ul,{children:["\n",(0,t.jsx)(r.li,{children:"Abre el monitor serie para recibir los datos del sensor incluyendo temperatura, valor de presi\xf3n barom\xe9trica, presi\xf3n atmosf\xe9rica relativa y altitud."}),"\n"]}),"\n",(0,t.jsx)(r.p,{children:(0,t.jsx)(r.img,{src:"https://files.seeedstudio.com/wiki/Xadow_Barometer_BMP180/img/Barometer_Sensor.jpg",alt:""})}),"\n",(0,t.jsxs)(r.ul,{children:["\n",(0,t.jsx)(r.li,{children:"Lo siguiente es un gr\xe1fico de referencia que traza la relaci\xf3n entre la altitud sobre el nivel del mar y la presi\xf3n barom\xe9trica."}),"\n"]}),"\n",(0,t.jsx)(r.p,{children:(0,t.jsx)(r.img,{src:"https://files.seeedstudio.com/wiki/Xadow_Barometer_BMP180/img/Pressure_and_Altitude.jpg",alt:""})}),"\n",(0,t.jsx)(r.h2,{id:"visor-de-esquemas-en-l\xednea",children:"Visor de Esquemas en L\xednea"}),"\n",(0,t.jsx)("div",{className:"altium-ecad-viewer","data-project-src":"https://files.seeedstudio.com/wiki/Xadow_Barometer_BMP180/res/Xadow_-_Barometer_BMP180_v1.0_sch_pcb.zip",style:{borderRadius:"0px 0px 4px 4px",height:500,borderStyle:"solid",borderWidth:1,borderColor:"rgb(241, 241, 241)",overflow:"hidden",maxWidth:1280,maxHeight:700,boxSizing:"border-box"}}),"\n",(0,t.jsx)(r.h2,{id:"recursos",children:"Recursos"}),"\n",(0,t.jsx)(r